export interface Destination {
  id: string;
  name: string;
  image: string;
  price: string;
  description: string;
  tag?: string;
  country?: string;
  region?: string;
  duration?: string;
  bestTime?: string;
  highlights?: string[];
  gallery?: string[];
  isFeatured?: boolean;
  tagline?: string;
  overview?: string;
  startingPoint?: string;
  groupSize?: string;
  themes?: string[];
  characterTitle?: string;
  planningTitle?: string;
  planningDescription?: string;
  planningPoints?: string[];
  experiences?: DestinationExperience[];
  route?: DestinationRouteStop[];
  seasons?: DestinationSeason[];
  designerNotes?: string[];
  itinerary?: ItineraryDay[];
  inclusions?: string[];
  exclusions?: string[];
  faqs?: PackageFaq[];
  status?: "draft" | "active";
}

export interface DestinationExperience {
  title: string;
  description: string;
}

export interface DestinationRouteStop {
  label: string;
  title: string;
  description: string;
}

export interface DestinationSeason {
  title: string;
  detail: string;
}

export interface ItineraryDay {
  day: number;
  title: string;
  description: string;
  meals: string;
  stay?: string;
}

export interface PackageFaq {
  question: string;
  answer: string;
}

export interface PackageGalleryImage {
  image: string;
  caption: string;
}

export interface PackageAddon {
  id: string;
  title: string;
  description?: string;
  price: number;
  pricing: "per-person" | "per-booking";
}

export interface PackagePricing {
  adultPrice: number;
  childWithBedPrice: number;
  childWithoutBedPrice: number;
  infantPrice: number;
  singleRoomSupplement: number;
  depositPercent: number;
  quoteValidityDays: number;
  addons: PackageAddon[];
}

export const PACKAGE_SERVICE_KEYS = ["hotel", "meals", "flights", "sightseeing", "transfer", "visa"] as const;
export type PackageServiceKey = (typeof PACKAGE_SERVICE_KEYS)[number];

/** Detailed service notes shown in the package inclusion tabs. */
export interface PackageServiceDetails {
  kind: PackageServiceKey;
  items: string[];
}

export interface TourPackage {
  id: string;
  title: string;
  image: string;
  duration: string;
  price: string;
  highlights: string[];
  category: string;
  isPopular?: boolean;
  tagline?: string;
  overview?: string;
  heroImage?: string;
  bestTime?: string;
  startingPoint?: string;
  groupSize?: string;
  themes?: string[];
  itinerary?: ItineraryDay[];
  inclusions?: string[];
  exclusions?: string[];
  serviceDetails?: PackageServiceDetails[];
  gallery?: PackageGalleryImage[];
  faqs?: PackageFaq[];
  pricing?: PackagePricing;
  brochureUrl?: string;
  status?: "draft" | "active";
}

export interface WhyChooseItem {
  id: string;
  title: string;
  description: string;
  stat?: string;
  iconName: "experience" | "happy" | "planning" | "support";
}

export interface Testimonial {
  id: string;
  name: string;
  photo: string;
  destination: string;
  review: string;
  rating: number;
}

export interface GalleryItem {
  id: string;
  image: string;
  location: string;
  title: string;
}

export interface BlogPost {
  id: string;
  slug: string;
  title: string;
  excerpt: string;
  content: string; // body; blank lines separate paragraphs
  coverImage: string;
  author: string;
  category: string;
  readTime: string;
  date: string; // display string, e.g. "20 Jul 2026"
  isPublished: boolean;
}

